<script setup>
import { computed, onMounted } from "vue";
import { useSiteStore } from "@/store/site";

const site = useSiteStore();
onMounted(() => site.load());

const s = computed(() => site.settings || {});
const menus = computed(() => site.menus || {});

// 0-9 -> ০-৯
const bn = (v) => String(v ?? "").replace(/\d/g, (d) => "০১২৩৪৫৬৭৮৯"[d]);

const EXTERNAL = /^(https?:)?\/\/|^(mailto|tel):/i;

// Turn a menu item from the API into a router link or a plain anchor
function toLink(m) {
  const base = { id: m.id, label: m.label, newTab: !!m.new_tab };
  if (m.type === "category") {
    return { ...base, to: `${encodeURIComponent(m.slug)}` };
  }
  if (m.type === "sub_category") {
    return {
      ...base,
      to: m.category_slug
        ? `${encodeURIComponent(m.category_slug)}/${encodeURIComponent(m.slug)}`
        : `${encodeURIComponent(m.slug)}`,
    };
  }
  const url = m.url || "/";
  return EXTERNAL.test(url) ? { ...base, href: url } : { ...base, to: url };
}

const COLUMN_DEFS = [
  { key: "footer_sections", title: "বিভাগসমূহ" },
  { key: "footer_quick", title: "দ্রুত লিংক" },
  { key: "footer_about", title: "আমাদের সম্পর্কে" },
];

const linkColumns = computed(() =>
  COLUMN_DEFS
    .map((c) => ({ ...c, links: (menus.value[c.key] || []).map(toLink) }))
    .filter((c) => c.links.length > 0)
);

const phones = computed(() => [s.value.contact_phone, s.value.contact_phone_secondary].filter(Boolean));
const hasContact = computed(
  () => phones.value.length || s.value.contact_email || s.value.ads_email || s.value.office_address || s.value.map_url
);

// number of grid columns after the brand column
const extraCols = computed(() => linkColumns.value.length + (hasContact.value ? 1 : 0));

const socials = computed(() =>
  [
    { key: "facebook", label: "Facebook", icon: "f", href: s.value.facebook_url },
    { key: "twitter", label: "Twitter", icon: "𝕏", href: s.value.twitter_url },
    { key: "instagram", label: "Instagram", icon: "📷", href: s.value.instagram_url },
    { key: "youtube", label: "YouTube", icon: "▶", href: s.value.youtube_url },
    { key: "linkedin", label: "LinkedIn", icon: "in", href: s.value.linkedin_url },
  ].filter((x) => x.href)
);

// Editor / publisher / registration: the imprint line Bangladeshi newspapers carry
const imprint = computed(() => {
  const out = [];
  const ed = s.value.editor_name;
  const pub = s.value.publisher_name;
  if (ed && pub && ed === pub) out.push({ label: "সম্পাদক ও প্রকাশক", value: ed });
  else {
    if (ed) out.push({ label: "সম্পাদক", value: ed });
    if (pub) out.push({ label: "প্রকাশক", value: pub });
  }
  if (s.value.registration_number) out.push({ label: "নিবন্ধন নং", value: bn(s.value.registration_number) });
  return out;
});

const copyright = computed(
  () => s.value.copyright_text || `© ${bn(new Date().getFullYear())} ${s.value.site_name || ""} সর্বস্বত্ব সংরক্ষিত।`
);

const toTop = () => window.scrollTo({ top: 0, behavior: "smooth" });
</script>

<template>
  <footer v-if="site.loaded" class="footer">
    <div class="inner">
      <!-- Main grid: brand | sections | quick links | about | contact -->
      <div class="main" :style="{ '--cols': extraCols }">
        <section class="brand">
          <router-link to="/" class="brand-link" :aria-label="s.site_name || 'হোম'">
            <span v-if="s.logo" class="logo-tile"><img :src="s.logo" :alt="s.site_name" /></span>
            <span v-if="s.site_name" class="name">{{ s.site_name }}</span>
          </router-link>
          <p v-if="s.site_slogan" class="slogan">{{ s.site_slogan }}</p>
          <p v-if="s.site_description" class="desc">{{ s.site_description }}</p>

          <div v-if="socials.length" class="social">
            <span class="social-label">আমাদের অনুসরণ করুন</span>
            <div class="social-links">
              <a
                v-for="x in socials" :key="x.key"
                :href="x.href" target="_blank" rel="noopener noreferrer" :aria-label="x.label"
              ><i class="icon">{{ x.icon }}</i></a>
            </div>
          </div>
        </section>

        <nav v-for="col in linkColumns" :key="col.key" class="links" :aria-label="col.title">
          <h4>{{ col.title }}</h4>
          <ul :class="{ split: col.links.length > 6 }">
            <li v-for="l in col.links" :key="l.id">
              <a
                v-if="l.href" :href="l.href"
                :target="l.newTab ? '_blank' : null" :rel="l.newTab ? 'noopener noreferrer' : null"
              >{{ l.label }}</a>
              <router-link v-else :to="l.to" :target="l.newTab ? '_blank' : null">{{ l.label }}</router-link>
            </li>
          </ul>
        </nav>

        <section v-if="hasContact" class="contact">
          <h4>যোগাযোগ</h4>
          <div v-if="s.office_address" class="contact-item">
            <span class="contact-icon" aria-hidden="true">📍</span>
            <p>{{ s.office_address }}</p>
          </div>
          <div v-if="phones.length" class="contact-item">
            <span class="contact-icon" aria-hidden="true">📞</span>
            <p>
              <template v-for="(p, i) in phones" :key="p">
                <br v-if="i > 0" />
                <a :href="'tel:' + p">{{ bn(p) }}</a>
              </template>
            </p>
          </div>
          <div v-if="s.contact_email" class="contact-item">
            <span class="contact-icon" aria-hidden="true">📧</span>
            <p><a :href="'mailto:' + s.contact_email">{{ s.contact_email }}</a></p>
          </div>
          <div v-if="s.ads_email" class="contact-item">
            <span class="contact-icon" aria-hidden="true">📢</span>
            <p>বিজ্ঞাপন: <a :href="'mailto:' + s.ads_email">{{ s.ads_email }}</a></p>
          </div>
          <div v-if="s.map_url" class="contact-item">
            <span class="contact-icon" aria-hidden="true">🗺</span>
            <p><a :href="s.map_url" target="_blank" rel="noopener noreferrer">মানচিত্রে দেখুন</a></p>
          </div>
        </section>
      </div>

      <!-- Editor / publisher / registration -->
      <div v-if="imprint.length" class="imprint">
        <span v-for="(i, idx) in imprint" :key="i.label" class="imprint-item">
          <span v-if="idx > 0" class="dot" aria-hidden="true">•</span>
          {{ i.label }}: <strong>{{ i.value }}</strong>
        </span>
      </div>

      <!-- Bottom bar -->
      <div class="bottom">
        <p class="copyright">{{ copyright }}</p>
        <button type="button" class="to-top" @click="toTop">↑ উপরে যান</button>
      </div>
    </div>
  </footer>
</template>

<style scoped>
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+Bengali:wght@400;500;600;700&family=Noto+Serif+Bengali:wght@600;700&display=swap');

.footer {
  background: linear-gradient(to bottom, #1a1a1a, #000);
  color: #b0b0b0;
  font-family: 'Noto Sans Bengali', 'SolaimanLipi', sans-serif;
  border-top: 4px solid #f21b3f;
  margin-top: 40px;
}
.inner { max-width: 1400px; margin: 0 auto; }

/* Main grid */
.main {
  display: grid;
  grid-template-columns: 1.7fr repeat(var(--cols, 3), 1fr);
  gap: 40px;
  padding: 52px 40px 36px;
}
.main > * { min-width: 0; }

h4 {
  color: #fff; font-family: 'Noto Serif Bengali', serif; font-size: 18px; font-weight: 700;
  margin: 0 0 18px; padding-bottom: 10px; border-bottom: 2px solid #f21b3f; display: inline-block;
}

/* Brand */
.brand-link { display: inline-flex; align-items: center; gap: 14px; text-decoration: none; margin-bottom: 14px; }
.logo-tile { background: #fff; border-radius: 6px; padding: 6px 10px; display: inline-flex; }
.logo-tile img { height: 48px; max-width: 150px; object-fit: contain; display: block; }
.name { font-family: 'Noto Serif Bengali', serif; font-size: 26px; font-weight: 700; color: #fff; line-height: 1.3; }
.slogan { color: #f7c948; font-weight: 600; font-size: 14px; margin: 0 0 8px; }
.desc { font-size: 14px; line-height: 1.8; margin: 0 0 22px; color: #b0b0b0; }

.social-label { display: block; font-size: 13px; color: #888; margin-bottom: 10px; }
.social-links { display: flex; gap: 10px; flex-wrap: wrap; }
.social-links a {
  width: 40px; height: 40px; background: #2a2a2a; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  color: #b0b0b0; text-decoration: none; font-size: 16px; transition: all 0.3s;
}
.social-links a:hover { background: linear-gradient(135deg, #006a4e 0%, #f21b3f 100%); color: #fff; transform: translateY(-3px); }
.social-links a:focus-visible { outline: 2px solid #f7c948; outline-offset: 2px; }
.icon { font-style: normal; }

/* Link columns */
.links ul { list-style: none; margin: 0; padding: 0; }
.links ul.split { column-count: 2; column-gap: 24px; }
.links li { margin-bottom: 12px; break-inside: avoid; }
.links a {
  color: #b0b0b0; text-decoration: none; font-size: 14px; display: inline-block;
  transition: color 0.3s, padding-left 0.3s;
}
.links a:hover { color: #f21b3f; padding-left: 8px; }
.links a:focus-visible { outline: 2px solid #f7c948; outline-offset: 2px; }

/* Contact */
.contact-item { display: flex; gap: 12px; margin-bottom: 16px; align-items: flex-start; }
.contact-icon { font-size: 17px; min-width: 22px; }
.contact-item p { margin: 0; line-height: 1.6; font-size: 14px; }
.contact-item a { color: #b0b0b0; text-decoration: none; transition: color 0.3s; word-break: break-word; }
.contact-item a:hover { color: #f21b3f; }

/* Imprint */
.imprint {
  margin: 0 40px; padding: 18px 0; border-top: 1px solid #2a2a2a; border-bottom: 1px solid #2a2a2a;
  display: flex; flex-wrap: wrap; justify-content: center; gap: 6px 14px;
  font-size: 14px; color: #b0b0b0; text-align: center;
}
.imprint strong { color: #fff; font-weight: 600; }
.dot { color: #f21b3f; margin-right: 14px; }

/* Bottom bar */
.bottom {
  display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 14px;
  padding: 22px 40px;
}
.copyright { margin: 0; color: #777; font-size: 14px; }
.to-top {
  font: inherit; font-size: 13px; font-weight: 600; color: #fff; background: #2a2a2a;
  border: 1px solid #3a3a3a; border-radius: 50px; padding: 8px 18px; cursor: pointer; transition: all 0.3s;
}
.to-top:hover { background: #f21b3f; border-color: #f21b3f; }
.to-top:focus-visible { outline: 2px solid #f7c948; outline-offset: 2px; }

/* Responsive */
@media (max-width: 1100px) {
  .main { grid-template-columns: repeat(3, 1fr); }
  .brand { grid-column: 1 / -1; }
}
@media (max-width: 768px) {
  .main { grid-template-columns: 1fr 1fr; padding: 40px 20px 28px; gap: 30px; }
  .contact { grid-column: 1 / -1; }
  .imprint { margin: 0 20px; flex-direction: column; align-items: center; }
  .dot { display: none; }
  .bottom { padding: 20px; flex-direction: column; text-align: center; }
}
@media (max-width: 480px) {
  .main { grid-template-columns: 1fr; padding: 32px 15px 24px; }
  .brand-link { flex-direction: column; align-items: flex-start; }
  .imprint { margin: 0 15px; }
  .bottom { padding: 20px 15px; }
}
</style>